const topicGroups = [
[['Permissions & least privilege','Read, write, and execute apply separately to owner, group, and others. Directory execute means permission to traverse it.','Use chmod 640 for a private configuration file shared with a group.','Avoid chmod 777 as a debugging shortcut; identify the process user first.'],['DNS, ports & TLS','DNS resolves a name; TCP connects to a port; TLS authenticates and encrypts the connection; HTTP carries the request.','If DNS resolves but curl cannot connect, inspect listeners and firewall rules.','A valid DNS response does not prove that the application is healthy.'],['Exit codes & shell safety','Exit code 0 means success. Quote variables to avoid unintended word splitting. Treat script inputs as data.','Use a nonzero exit when a health check fails so CI can block delivery.','set -e has exceptions; explicitly handle failures where control flow matters.']],
[['Commits, branches & review','A branch points to a commit. Small commits and focused pull requests make intent easier to review.','Separate a configuration change from a large refactor.','Never commit secrets; removing them in a later commit does not erase history.'],['Revert versus reset','Revert creates an inverse commit; reset moves a local branch reference and may alter local files.','Use revert for a shared release commit so the rollback is reviewable.','Rewriting shared history can invalidate collaborators’ work.'],['Immutable release identity','A release should map to an exact source revision and artifact digest.','Record the commit SHA beside the container digest in release notes.','A mutable tag such as latest can point to different contents tomorrow.']],
[['Images, layers & containers','An image is a layered package. A container is an isolated running process using that image.','Use multi-stage builds to keep compilers out of the runtime image.','A small image is useful, but it does not automatically mean a secure image.'],['Volumes & persistence','Container writable layers are disposable. Volumes decouple durable data from container replacement.','Store database files on a managed volume and test a restore.','A persistent volume is not a backup.'],['Networks & port publishing','Containers on a shared Compose network can resolve service names. Published ports expose a service on the host.','Your API connects to database:5432 inside the Compose network.','localhost inside a container refers to that container, not the host or a sibling.']],
[['CI gates & artifact promotion','Test source, build once, scan the artifact, then promote the same digest between environments.','Use job dependencies so failed checks prevent publication.','Rebuilding for production can produce a different artifact from the one tested.'],['Secrets & short-lived identity','Keep credentials outside source. Prefer scoped, short-lived credentials when the provider supports them.','Restrict a deployment identity to one environment and only the required operations.','Do not pass deployment credentials to untrusted pull request code.'],['Supply-chain evidence','An SBOM inventories components; a signature establishes artifact provenance under a trust policy.','Attach scan results and provenance to the image digest.','A signature alone does not prove the software is free of vulnerabilities.']],
[['State, locking & drift','State maps configuration to actual resources. Locking prevents concurrent state writes where the backend supports it.','Review a plan after a manual resource change to identify drift.','Do not fix shared state with ad hoc edits.'],['Sensitive state','Marking a value sensitive hides it in normal output; it can still exist in state. Protect backend access and backups.','Use encrypted remote storage and narrowly scoped access for state.','Sensitive output redaction is not state encryption.'],['Modules & change boundaries','A module groups a coherent infrastructure capability behind inputs and outputs.','Keep application and foundational network changes reviewable separately.','Large all-in-one state files increase the scope of a failed change.']],
[['Readiness, liveness & startup','Readiness controls traffic eligibility. Liveness can restart a stuck container. A startup probe delays the other checks during initialization.','Use a readiness endpoint for traffic and a narrowly scoped liveness check.','A dependency outage should not trigger restart loops across otherwise healthy application containers.'],['Requests, limits & scheduling','Requests inform placement. CPU limits can throttle; memory limits can lead to termination when exceeded.','Measure workload usage, then set requests with room for expected variation.','Low requests can hide capacity pressure; aggressive limits can create latency.'],['Reconciliation & GitOps','A controller compares desired and observed state and works to reduce the difference. Git provides a reviewable desired state.','Change an image digest in Git, then observe sync and health separately.','A successful sync does not guarantee that the application serves correct responses.']],
[['SLI, SLO & error budget','An SLI measures user-visible behavior. An SLO sets a target over a window. The error budget is the allowed failure fraction.','A 99.9% request-success target permits 1,000 failed requests per million eligible requests.','Request-based budgets do not directly convert into minutes of downtime.'],['Metrics, logs & traces','Metrics describe aggregate trends, logs describe events, and traces connect work across services.','Start with an error-rate spike, inspect relevant traces, then read correlated logs.','High-cardinality labels such as user IDs can make metrics expensive.'],['Actionable alerts','Alert on meaningful user impact with a clear owner and response. Use a duration or burn-rate strategy to reduce noise.','Link each alert to a short diagnostic and recovery runbook.','Every warning does not need to page someone.']],
[['Canary & blue-green releases','A canary exposes a subset of traffic to a change; blue-green maintains two environments and switches traffic.','Compare error rate and latency before expanding the canary.','A reversible traffic switch does not undo an incompatible database migration.'],['RTO, RPO & restore drills','RTO is a recovery-time objective. RPO is the acceptable data-loss window. Both need evidence from drills.','Restore a backup into an isolated environment and measure elapsed time.','A successful backup job does not prove that recovery works.'],['Incident learning & delivery metrics','Document impact, timeline, contributing conditions, and follow-up work. Track delivery speed together with stability.','Measure change lead time and recovery behavior across several releases.','Avoid turning incident reviews or delivery metrics into individual blame.']]
];
function conceptDetails(i){return `<section class="concept-notes"><div class="eyebrow">THE DETAILS THAT MATTER</div>${topicGroups[i].map(t=>`<details><summary>${t[0]}<span>+</span></summary><p>${t[1]}</p><div class="note-example"><b>IN PRACTICE</b><p>${t[2]}</p></div><p class="pitfall"><b>Watch for</b> · ${t[3]}</p></details>`).join('')}</section>`}
function conceptPage(){return title('Understand the important details.','24 concise field notes. The why, the example, and the mistake to avoid.')+`<div class="filter-bar"><input class="search" id="concept-search" aria-label="Search concepts" placeholder="Search probes, state, error budgets…"><select id="concept-filter" aria-label="Filter concepts by module"><option value="all">All disciplines</option>${modules.map((m,i)=>`<option value="${i}">${m.title}</option>`).join('')}</select></div><div id="concept-results"></div>`}
function drawConcepts(){const q=$('#concept-search').value.toLowerCase(),group=$('#concept-filter').value;let count=0;$('#concept-results').innerHTML=topicGroups.map((topics,i)=>{if(group!=='all'&&Number(group)!==i)return '';const found=topics.filter(t=>t.join(' ').toLowerCase().includes(q));count+=found.length;return found.length?`<section class="concept-section"><div class="section-head"><h2><span class="chapter-number">0${i+1}</span> ${modules[i].title}</h2><button class="text-button" data-lesson="${i}">Open module ↗</button></div><div class="grid">${found.map(t=>`<article class="card concept-card"><span class="tag">FIELD NOTE / 0${i+1}</span><h3>${t[0]}</h3><p>${t[1]}</p><details><summary>Example & common mistake <span>+</span></summary><p>${t[2]}</p><p class="pitfall">${t[3]}</p></details></article>`).join('')}</div></section>`:''}).join('')||'<p class="empty">No matching topics. Try “state”, “probes”, or “release”.</p>';document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)))}
